            InputEngine.UnicodeTextOutputForTest=null;InputEngine.KeyOutputForTest=null;
            var modifierDragKeys=new List<(ushort Key,bool Up)>();var modifierDragMouse=new List<uint>();InputEngine.KeyOutputForTest=(key,up)=>{modifierDragKeys.Add((key,up));return true;};InputEngine.MouseFlagOutputForTest=(flag,_)=>modifierDragMouse.Add(flag);
            InputEngine.SendMouse("ShiftDrag");Check(modifierDragKeys.SequenceEqual(new[]{((ushort)0x10,false),((ushort)0x10,true)})&&modifierDragMouse.SequenceEqual(new uint[]{2,4})&&!InputEngine.HasInjectedInputForTest(),"Shift drag single press sends Shift+left click and releases both");
            modifierDragKeys.Clear();modifierDragMouse.Clear();InputEngine.SendMouse("ShiftDrag:Start");Check(modifierDragKeys.SequenceEqual(new[]{((ushort)0x10,false)})&&modifierDragMouse.SequenceEqual(new uint[]{2})&&InputEngine.HasInjectedInputForTest(),"Shift drag start holds Shift and synthetic left down");InputEngine.SendMouse("ShiftDrag:End");Check(modifierDragKeys.LastOrDefault()==((ushort)0x10,true)&&modifierDragMouse.LastOrDefault()==4&&!InputEngine.HasInjectedInputForTest(),"Shift drag end releases left before Shift");int endedKeyCount=modifierDragKeys.Count,endedMouseCount=modifierDragMouse.Count;InputEngine.SendMouse("ShiftDrag:End");Check(modifierDragKeys.Count==endedKeyCount&&modifierDragMouse.Count==endedMouseCount,"duplicate drag end never injects unrelated releases");
            modifierDragKeys.Clear();modifierDragMouse.Clear();InputEngine.SendMouse("CtrlDrag");Check(modifierDragKeys.SequenceEqual(new[]{((ushort)0x11,false),((ushort)0x11,true)})&&modifierDragMouse.SequenceEqual(new uint[]{2,4})&&!InputEngine.HasInjectedInputForTest(),"Ctrl drag single press sends Ctrl+left click and releases both");InputEngine.SendMouse("CtrlDrag:Start");engine.ResetStateForTest();Check(!InputEngine.HasInjectedInputForTest()&&modifierDragMouse.SequenceEqual(new uint[]{2,4,2,4})&&modifierDragKeys.LastOrDefault()==((ushort)0x11,true),"state reset safely releases an interrupted Ctrl drag");modifierDragKeys.Clear();modifierDragMouse.Clear();InputEngine.PhysicalKeyDownForTest=_=>false;InputEngine.SendMouse("CtrlDrag:Start");await Task.Delay(220);Check(!InputEngine.HasInjectedInputForTest()&&modifierDragMouse.LastOrDefault()==4&&modifierDragKeys.LastOrDefault()==((ushort)0x11,true),"physical mouse release watchdog ends Ctrl drag even when its hook end event is lost");InputEngine.PhysicalKeyDownForTest=null;InputEngine.MouseFlagOutputForTest=null;InputEngine.KeyOutputForTest=null;
            InputEngine.KeyOutputForTest=(_,_)=>true;InputEngine.MouseFlagOutputForTest=(_,_)=>{};foreach(string name in new[]{"A","Ctrl","Shift","Alt","Win","Space","CapsLock"})InputEngine.SendRecordedEvent(name+" Down");foreach(string name in new[]{"MouseLeft","MouseRight","MouseMiddle","MouseBack","MouseForward"})InputEngine.SendRecordedEvent(name+" Down");Check(InputEngine.HasInjectedInputForTest(),"all generated key and mouse button downs are tracked");InputEngine.ExpireInjectedInputsForTest();Check(!InputEngine.HasInjectedInputForTest(),"stale-input watchdog releases Ctrl, every tracked key, and every mouse button");InputEngine.MouseFlagOutputForTest=null;int keyUpAttempts=0;InputEngine.KeyOutputForTest=(_,up)=>!up||++keyUpAttempts>=3;InputEngine.SendRecordedEvent("A Down");InputEngine.ReleaseAll();Check(keyUpAttempts==3&&!InputEngine.HasInjectedInputForTest(),"failed key-up output is retried until released");InputEngine.KeyOutputForTest=null;
            InputEngine.MouseFlagOutputForTest=(_,_)=>{};MacroPlayer.Play(new MacroDefinition{Name="incomplete mouse macro",Steps=[new(){Event="MouseLeft Down"}]});await Task.Delay(120);Check(!InputEngine.HasInjectedInputForTest(),"macro completion releases an unmatched mouse down");InputEngine.MouseFlagOutputForTest=null;
            var invalidMacroResult=await MacroPlayer.PlayAsync(new MacroDefinition{Name="invalid macro",Steps=[new(){Event="Unknown Down"}]});Check(!invalidMacroResult.Succeeded&&!invalidMacroResult.Cancelled&&invalidMacroResult.Message.Length>0,"macro playback reports an invalid step instead of silently failing");
            var recursiveMacro=new MacroDefinition{Name="recursive macro"};recursiveMacro.Steps.Add(new MacroStep{Event="割り当て: recursive macro",RecordedActionKind=ActionKind.Macro,RecordedActionValue=recursiveMacro.Name});var recursiveConfig=new AppConfig{Macros=[recursiveMacro]};var recursiveResult=await MacroPlayer.PlayAsync(recursiveMacro,recursiveConfig);Check(!recursiveResult.Succeeded&&!recursiveResult.Cancelled&&recursiveResult.ExecutedSteps<=2,"recursive macro playback stops safely with a visible failure result");
            var delayedMacro=new MacroDefinition{Name="cancel macro",Steps=[new(){Event="Wait",DelayMs=3000}]};var delayedTask=MacroPlayer.PlayAsync(delayedMacro);await Task.Delay(30);MacroPlayer.StopAll();var cancelledResult=await delayedTask;Check(cancelledResult.Cancelled&&!InputEngine.HasInjectedInputForTest(),"macro test can be stopped immediately and releases generated input");
