            rightWheelLayer=true;engine.ResetStateForTest();events.Clear();var started=Environment.TickCount64;InputEngine.InjectMouseForTest("Right",false);await Task.Delay(100);for(int i=0;i<50;i++){InputEngine.InjectWheelForTest(true);await Task.Delay(10);}await Task.Delay(100);InputEngine.InjectMouseForTest("Right",true);await Task.Delay(200);int wheelEvents=events.Count(x=>x=="MouseRight+WheelUp");Check(wheelEvents>=35,$"right-click layer continuous wheel detection under synthetic input ({wheelEvents}/50)");
            int keyOutputCount=0,mouseOutputCount=0;InputEngine.KeyOutputForTest=(_,_)=>{Interlocked.Increment(ref keyOutputCount);return true;};InputEngine.MouseFlagOutputForTest=(_,_)=>Interlocked.Increment(ref mouseOutputCount);started=Environment.TickCount64;await Task.Run(()=>{for(int i=0;i<50;i++)InputEngine.SendShortcut(i%2==0?"Ctrl+WheelUp":"Ctrl+WheelDown");});await Task.Delay(50);Check(Environment.TickCount64-started<3000&&keyOutputCount==100&&mouseOutputCount==50&&!InputEngine.HasInjectedInputForTest(),"continuous Ctrl+wheel output on worker and modifier release");InputEngine.KeyOutputForTest=null;InputEngine.MouseFlagOutputForTest=null;rightWheelLayer=false;engine.ResetStateForTest();
